BEGIN;
-- Source adapters preserve each module's authorization and real accounting basis.
CREATE FUNCTION erp_reports_private.legacy_voucher_facts(c uuid,s text,f date,t date) RETURNS SETOF jsonb LANGUAGE plpgsql SET search_path='' AS $$BEGIN
 RETURN QUERY SELECT erp_reports_private.fact(d.id::text,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('number',d.number,'name',d.note,'note',d.note,'category','','account',ac.name,'customer',CASE WHEN p.kind='customer' THEN p.name ELSE '' END,'supplier',CASE WHEN p.kind='supplier' THEN p.name ELSE '' END,'net',CASE WHEN s='expenses' THEN coalesce((SELECT sum(j.debit-j.credit) FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=c AND j.document_id=d.id AND a.kind='expense'),0) ELSE sign*d.total-coalesce((SELECT sum(j.credit-j.debit) FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=c AND j.document_id=d.id AND a.kind='vat_output'),0) END,'tax',coalesce((SELECT sum(CASE WHEN s='expenses' THEN j.debit-j.credit ELSE j.credit-j.debit END) FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=c AND j.document_id=d.id AND a.kind=CASE s WHEN 'expenses' THEN 'vat_input' ELSE 'vat_output' END),0),'amount',sign*d.total,'currency','SAR','status',CASE WHEN sign<0 THEN 'reversal' ELSE 'posted' END)) FROM public.bf_documents d LEFT JOIN public.bf_documents parent ON parent.cafe_id=d.cafe_id AND parent.id=d.reference_id LEFT JOIN public.bf_parties p ON p.cafe_id=d.cafe_id AND p.id=coalesce(d.party_id,parent.party_id) LEFT JOIN public.bf_accounts ac ON ac.cafe_id=d.cafe_id AND ac.id=coalesce(d.account_id,parent.account_id) CROSS JOIN LATERAL(SELECT CASE WHEN d.kind='journal' THEN -1 ELSE 1 END sign)x WHERE d.cafe_id=c AND(d.kind=CASE s WHEN 'expenses' THEN 'expense' ELSE 'receipt' END OR d.kind='journal' AND parent.kind=CASE s WHEN 'expenses' THEN 'expense' ELSE 'receipt' END) AND NOT EXISTS(SELECT 1 FROM public.erp_finance_vouchers v WHERE v.cafe_id=c AND d.id IN(v.document_id,v.reversal_id));
END $$;
CREATE FUNCTION erp_reports_private.customer_facts(c uuid,s text,f date,t date) RETURNS SETOF jsonb LANGUAGE plpgsql SET search_path='' AS $$DECLARE x jsonb;r jsonb;BEGIN
 IF s IN('customers','suppliers') THEN
  RETURN QUERY SELECT erp_reports_private.fact(p.id::text,NULL,jsonb_build_object('name',p.name,'customer',CASE WHEN p.kind='customer' THEN p.name ELSE '' END,'supplier',CASE WHEN p.kind='supplier' THEN p.name ELSE '' END,'phone',to_jsonb(p)->>'phone','email',to_jsonb(p)->>'email','country',to_jsonb(p)->>'country','state',to_jsonb(p)->>'state','city',to_jsonb(p)->>'city','status',CASE WHEN p.active THEN 'active' ELSE 'inactive' END,'href','/dashboard/system/'||CASE WHEN p.kind='customer' THEN 'customers/' ELSE 'purchases/suppliers/' END||p.id)) FROM public.bf_parties p WHERE p.cafe_id=c AND p.kind=CASE s WHEN 'customers' THEN 'customer' ELSE 'supplier' END;RETURN;
 ELSIF s IN('customer-aging','supplier-aging') THEN
  -- Document balances are current, aged against the selected closing date.
  RETURN QUERY WITH invoices AS(SELECT p.id,p.name,coalesce(nullif(to_jsonb(e)->>'due_date','')::date,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date) due,(brand_finance_private.document_state(c,d.id)->>'outstanding')::numeric amount FROM public.bf_documents d JOIN public.bf_parties p ON p.cafe_id=d.cafe_id AND p.id=d.party_id LEFT JOIN public.bf_invoice_extensions e ON e.cafe_id=d.cafe_id AND e.document_id=d.id WHERE d.cafe_id=c AND d.kind=CASE s WHEN 'customer-aging' THEN 'sale' ELSE 'purchase' END AND(d.created_at AT TIME ZONE 'Asia/Riyadh')::date<=t)
  SELECT erp_reports_private.fact(id::text,NULL,jsonb_build_object('name',name,'current',coalesce(sum(amount) FILTER(WHERE due>=t),0),'age30',coalesce(sum(amount) FILTER(WHERE t-due BETWEEN 1 AND 30),0),'age60',coalesce(sum(amount) FILTER(WHERE t-due BETWEEN 31 AND 60),0),'age90',coalesce(sum(amount) FILTER(WHERE t-due BETWEEN 61 AND 90),0),'ageOlder',coalesce(sum(amount) FILTER(WHERE t-due>90),0),'outstanding',sum(amount))) FROM invoices GROUP BY id,name;RETURN;
 ELSIF s='customer-credits' THEN
  RETURN QUERY SELECT erp_reports_private.fact(p.id::text,NULL,jsonb_build_object('customer',p.name,'name',p.name,'amount',brand_finance_private.customer_credit_balance(c,p.id),'remaining',brand_finance_private.customer_credit_balance(c,p.id),'status',CASE WHEN p.active THEN 'active' ELSE 'inactive' END)) FROM public.bf_parties p WHERE p.cafe_id=c AND p.kind='customer' AND brand_finance_private.customer_credit_balance(c,p.id)<>0;RETURN;
 ELSIF s='credit-charges' THEN
  RETURN QUERY SELECT erp_reports_private.fact(ch.id::text,ch.starts_on,jsonb_build_object('number',ch.number,'customer',p.name,'customerId',p.id,'type',ct.name,'typeId',ct.id,'unit',ct.unit,'quantity',ch.quantity,'remaining',ch.quantity-coalesce((SELECT sum(a.quantity) FROM public.erp_credit_allocations a WHERE a.cafe_id=c AND a.charge_id=ch.id),0),'starts',ch.starts_on,'ends',ch.expires_on,'status',CASE WHEN ch.suspended THEN 'suspended' WHEN ch.expires_on<current_date THEN 'expired' WHEN ch.starts_on>current_date THEN 'pending' ELSE 'active' END,'href','/dashboard/system/credits/charges/'||ch.id)) FROM public.erp_credit_charges ch JOIN public.bf_parties p ON p.cafe_id=ch.cafe_id AND p.id=ch.customer_id JOIN public.erp_credit_types ct ON ct.cafe_id=ch.cafe_id AND ct.id=ch.type_id WHERE ch.cafe_id=c;RETURN;
 ELSIF s='credit-usages' THEN
  RETURN QUERY SELECT erp_reports_private.fact(u.id::text,u.used_on,jsonb_build_object('number',u.number,'customer',p.name,'customerId',p.id,'type',ct.name,'typeId',ct.id,'unit',ct.unit,'quantity',CASE WHEN u.voided THEN 0 ELSE u.quantity END,'status',CASE WHEN u.voided THEN 'void' ELSE 'active' END,'href','/dashboard/system/credits/usages/'||u.id)) FROM public.erp_credit_usages u JOIN public.bf_parties p ON p.cafe_id=u.cafe_id AND p.id=u.customer_id JOIN public.erp_credit_types ct ON ct.cafe_id=u.cafe_id AND ct.id=u.type_id WHERE u.cafe_id=c;RETURN;
 ELSIF s='memberships' THEN
  RETURN QUERY SELECT erp_reports_private.fact(m.id::text,m.joined_on,jsonb_build_object('number',m.number,'customer',p.name,'customerId',p.id,'package',pkg.name,'starts',m.joined_on,'ends',(SELECT max(erp_membership_private.end_date(c,rr.id)) FROM public.erp_membership_renewals rr WHERE rr.cafe_id=c AND rr.membership_id=m.id AND rr.status='paid'),'status',erp_membership_private.status(c,m.id),'href','/dashboard/system/memberships/'||m.id)) FROM public.erp_memberships m JOIN public.bf_parties p ON p.cafe_id=m.cafe_id AND p.id=m.customer_id JOIN public.erp_credit_packages pkg ON pkg.cafe_id=m.cafe_id AND pkg.id=m.package_id WHERE m.cafe_id=c AND NOT m.deleted;RETURN;
 ELSIF s='membership-renewals' THEN
  RETURN QUERY SELECT erp_reports_private.fact(r.id::text,r.invoice_date,jsonb_build_object('number',r.number,'customer',p.name,'customerId',p.id,'package',pkg.name,'starts',r.starts_on,'ends',CASE WHEN r.starts_on IS NOT NULL THEN erp_membership_private.end_date(c,r.id) END,'amount',CASE WHEN r.invoice_id IS NULL THEN NULL ELSE r.invoice_total END,'paid',CASE WHEN r.invoice_id IS NULL THEN 0 ELSE(brand_finance_private.document_state(c,r.invoice_id)->>'paid')::numeric END,'status',r.status,'href','/dashboard/system/memberships/'||r.membership_id)) FROM public.erp_membership_renewals r JOIN public.bf_parties p ON p.cafe_id=r.cafe_id AND p.id=r.customer_id JOIN public.erp_credit_packages pkg ON pkg.cafe_id=r.cafe_id AND pkg.id=r.package_id WHERE r.cafe_id=c AND r.kind='membership';RETURN;
 END IF;RAISE EXCEPTION 'مصدر تقرير العملاء غير معروف';
END $$;
CREATE FUNCTION erp_reports_private.employee_dimensions(c uuid,i uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$SELECT jsonb_build_object('employee',concat_ws(' ',e.first_name,e.last_name),'employeeId',e.id,'department',coalesce(d.name,''),'departmentId',d.id,'designation',coalesce(des.name,''),'branch',coalesce(b.name,''),'branchId',b.id) FROM public.erp_hr_employees e LEFT JOIN public.erp_org_units d ON d.cafe_id=e.cafe_id AND d.id=e.department_id LEFT JOIN public.erp_org_units des ON des.cafe_id=e.cafe_id AND des.id=e.designation_id LEFT JOIN public.branches b ON b.cafe_id=e.cafe_id AND b.id=e.branch_id WHERE e.cafe_id=c AND e.id=i$$;
CREATE FUNCTION erp_reports_private.employee_facts(c uuid,s text,f date,t date) RETURNS SETOF jsonb LANGUAGE plpgsql SET search_path='' AS $$DECLARE snap jsonb;x jsonb;y jsonb;b jsonb;BEGIN
 IF s='employees' THEN
  RETURN QUERY SELECT erp_reports_private.fact(e.id::text,NULL,jsonb_build_object('number',e.code,'name',concat_ws(' ',e.first_name,e.last_name),'starts',e.payload->>'joinDate','ends',e.payload->>'endDate','status',CASE WHEN e.active THEN 'active' ELSE 'inactive' END,'href','/dashboard/system/employees/'||e.id)||erp_reports_private.employee_dimensions(c,e.id)) FROM public.erp_hr_employees e WHERE e.cafe_id=c;RETURN;
 ELSIF s='employee-documents' THEN
  RETURN QUERY SELECT erp_reports_private.fact(d.id::text,NULL,jsonb_build_object('number',d.number,'type',dt.name,'typeId',dt.id,'starts',d.issued_on,'ends',d.expires_on,'status',CASE WHEN d.expires_on<t THEN 'expired' ELSE 'valid' END,'expiry',CASE WHEN d.expires_on<t THEN 'expired' ELSE 'valid' END,'residency',CASE WHEN dt.name ILIKE '%إقام%' OR dt.name ILIKE '%اقام%' OR dt.name ILIKE '%residen%' THEN 'true' ELSE 'false' END)||erp_reports_private.employee_dimensions(c,d.employee_id)) FROM public.erp_hr_documents d JOIN public.erp_hr_document_types dt ON dt.cafe_id=d.cafe_id AND dt.id=d.type_id WHERE d.cafe_id=c;RETURN;
 ELSIF s='employee-compliance' THEN
  RETURN QUERY SELECT erp_reports_private.fact(e.id::text||':'||dt.id::text,NULL,jsonb_build_object('type',dt.name,'typeId',dt.id,'required',1,'present',CASE WHEN present THEN 1 ELSE 0 END,'missing',CASE WHEN present THEN 0 ELSE 1 END,'status',CASE WHEN present THEN 'complete' ELSE 'missing' END)||erp_reports_private.employee_dimensions(c,e.id)) FROM public.erp_hr_employees e JOIN public.erp_hr_document_types dt ON dt.cafe_id=e.cafe_id AND dt.required AND dt.active CROSS JOIN LATERAL(SELECT EXISTS(SELECT 1 FROM public.erp_hr_documents d WHERE d.cafe_id=c AND d.employee_id=e.id AND d.type_id=dt.id AND(d.expires_on IS NULL OR d.expires_on>=t))present)x WHERE e.cafe_id=c AND e.active;RETURN;
 ELSIF s='attendance' THEN
  RETURN QUERY SELECT erp_reports_private.fact(d.id::text,d.work_date,jsonb_build_object('type',coalesce(sh.name,''),'status',d.status,'scheduledHours',d.scheduled_minutes/60.0,'hours',d.worked_minutes/60.0,'days',CASE WHEN d.slot=0 THEN 1 ELSE 0 END,'lateMinutes',d.late_minutes,'earlyMinutes',d.early_minutes,'overtimeHours',d.overtime_minutes/60.0)||erp_reports_private.employee_dimensions(c,d.employee_id)) FROM public.erp_att_days d LEFT JOIN public.erp_att_shifts sh ON sh.cafe_id=d.cafe_id AND sh.id=d.shift_id WHERE d.cafe_id=c;RETURN;
 ELSIF s='leave-balance' THEN
  FOR x IN SELECT jsonb_build_object('employeeId',e.id,'typeId',lt.id,'type',lt.name) FROM public.erp_hr_employees e JOIN public.erp_att_leave_types lt ON lt.cafe_id=e.cafe_id WHERE e.cafe_id=c AND e.active LOOP
   b:=erp_attendance_private.balance(c,(x->>'employeeId')::uuid,(x->>'typeId')::uuid,t);
   RETURN NEXT erp_reports_private.fact(x->>'employeeId'||':'||(x->>'typeId'),NULL,x||erp_reports_private.employee_dimensions(c,(x->>'employeeId')::uuid)||jsonb_build_object('opening',(b->>'annual')::numeric,'received',(SELECT coalesce(sum(amount),0) FROM public.erp_att_balances WHERE cafe_id=c AND employee_id=(x->>'employeeId')::uuid AND leave_type_id=(x->>'typeId')::uuid AND fiscal_start=(b->>'fiscalStart')::date AND amount>0),'issued',(SELECT -coalesce(sum(amount),0) FROM public.erp_att_balances WHERE cafe_id=c AND employee_id=(x->>'employeeId')::uuid AND leave_type_id=(x->>'typeId')::uuid AND fiscal_start=(b->>'fiscalStart')::date AND amount<0),'remaining',(b->>'available')::numeric));
  END LOOP;RETURN;
 ELSIF s='shifts' THEN
  RETURN QUERY SELECT erp_reports_private.fact(sh.id::text||':'||(day->>'weekday'),NULL,jsonb_build_object('name',sh.name,'type',sh.payload->>'type','starts',day->>'start','ends',day->>'end','hours',CASE WHEN(day->>'working')::boolean THEN(extract(epoch FROM((day->>'end')::time-(day->>'start')::time))/60+CASE WHEN(day->>'end')::time<=(day->>'start')::time THEN 1440 ELSE 0 END-(day->>'breakMinutes')::numeric)/60 ELSE 0 END,'status',CASE WHEN sh.active THEN 'active' ELSE 'inactive' END,'note',(ARRAY['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'])[(day->>'weekday')::integer+1])) FROM public.erp_att_shifts sh CROSS JOIN LATERAL jsonb_array_elements(sh.payload->'days')day WHERE sh.cafe_id=c;RETURN;
 ELSIF s IN('contracts','payslips','loans') THEN
  snap:=public.erp_payroll_read(c);FOR x IN SELECT value FROM jsonb_array_elements(snap->s) LOOP
   RETURN NEXT erp_reports_private.fact(x->>'id',coalesce(nullif(x#>>'{payload,date}','')::date,(x->>'createdAt')::timestamptz::date),jsonb_build_object('number',x->>'code','name',x->>'name','starts',x#>>'{payload,start}','ends',x#>>'{payload,end}','amount',x->'total','paid',x->'paid','outstanding',CASE WHEN x->'total'='null'::jsonb THEN NULL ELSE(x->>'total')::numeric-(x->>'paid')::numeric END,'status',x->>'status','href','/dashboard/system/payroll/'||s||'/'||(x->>'id'))||coalesce(erp_reports_private.employee_dimensions(c,(x->>'employeeId')::uuid),'{}'));
  END LOOP;RETURN;
 END IF;RAISE EXCEPTION 'مصدر تقرير الموظفين غير معروف';
END $$;
CREATE FUNCTION erp_reports_private.linked_documents(c uuid,links jsonb,record_id uuid) RETURNS SETOF public.bf_documents LANGUAGE sql STABLE SET search_path='' AS $$
 WITH RECURSIVE ids(id) AS (
 SELECT (l->>'targetId')::uuid FROM jsonb_array_elements(coalesce(links,'[]')) l WHERE l->>'kind'='document' AND coalesce(l->>'recordId',l->>'orderId')=record_id::text
 UNION
 SELECT d.id FROM public.bf_documents d JOIN ids ON ids.id=d.reference_id WHERE d.cafe_id=c AND d.kind IN('refund','journal')
 ) SELECT d.* FROM public.bf_documents d JOIN ids ON ids.id=d.id WHERE d.cafe_id=c
$$;
CREATE FUNCTION erp_reports_private.operational_facts(c uuid,s text,f date,t date) RETURNS SETOF jsonb LANGUAGE plpgsql SET search_path='' AS $$DECLARE snap jsonb;x jsonb;y jsonb;dim jsonb;doc public.bf_documents;duration numeric;costs jsonb;BEGIN
 IF s='time' THEN
  snap:=public.erp_time_read(c,f,t);costs:=public.erp_time_cost_report(c,f,t);FOR x IN SELECT value FROM jsonb_array_elements(snap->'entries') LOOP
   IF x->>'end' IS NULL THEN CONTINUE;END IF;duration:=extract(epoch FROM least((x->>'end')::timestamptz,(t+1)::timestamp AT TIME ZONE 'Asia/Riyadh')-greatest((x->>'start')::timestamptz,f::timestamp AT TIME ZONE 'Asia/Riyadh'))/3600;IF duration<=0 THEN CONTINUE;END IF;
   RETURN NEXT erp_reports_private.fact(x->>'id',greatest(((x->>'start')::timestamptz AT TIME ZONE 'Asia/Riyadh')::date,f),jsonb_build_object('employee',x->>'workerName','employeeId',x->>'workerId','project',x->>'projectName','projectId',x->>'projectId','activity',x->>'activityName','hours',duration,'amount',CASE WHEN(x->>'billable')::boolean THEN round(duration*(x->>'billingRate')::numeric,2) ELSE 0 END,'estimatedCost',CASE WHEN(costs->>'enabled')::boolean THEN round(duration*(x->>'costRate')::numeric,2) ELSE 0 END,'cashPaid',0,'status',CASE WHEN x->>'invoiceId' IS NOT NULL THEN 'invoiced' WHEN x->>'batchId' IS NOT NULL THEN 'reserved' ELSE 'unbilled' END,'href','/dashboard/system/time/list'));
  END LOOP;RETURN;
 ELSIF s IN('workflows','work-orders','work-order-finance') THEN
  snap:=CASE WHEN s='workflows' THEN public.erp_workflows_read(c) ELSE public.erp_work_orders_read(c) END;
  FOR x IN SELECT value FROM jsonb_array_elements(snap->'records') LOOP
   dim:=jsonb_build_object('name',coalesce(x->>'title',x->>'name'),'number',x->>'code','customer',x->>'customerName','customerId',x->>'customerId','employee',x->>'assigneeName','employeeId',x->>'assigneeId','type',(SELECT value->>'name' FROM jsonb_array_elements(coalesce(snap->'types','[]')) WHERE value->>'id'=x->>'typeId'),'status',x->>'status','budget',x->'budget','category',coalesce(x->'tags','[]'),'href','/dashboard/system/'||CASE WHEN s='workflows' THEN 'workflows/'||(x->>'typeId')||'/' ELSE 'work-orders/' END||(x->>'id'));
   IF s<>'work-order-finance' THEN
    -- Link visibility is already filtered by workflow type/state/field permissions.
    SELECT jsonb_build_object('amount',coalesce(sum(CASE WHEN a.kind='revenue' THEN j.credit-j.debit ELSE 0 END),0),'cost',coalesce(sum(CASE WHEN a.kind='expense' THEN j.debit-j.credit ELSE 0 END),0),'profit',coalesce(sum(CASE WHEN a.kind IN('revenue','expense') THEN j.credit-j.debit ELSE 0 END),0)) INTO y FROM erp_reports_private.linked_documents(c,snap->'links',(x->>'id')::uuid) d JOIN public.bf_journal j ON j.cafe_id=c AND j.document_id=d.id JOIN public.bf_accounts a ON a.cafe_id=c AND a.id=j.account_id WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t;
    IF s='workflows' AND NOT coalesce(x#>'{allowedFields,read}','[]')?'budget' THEN y:='{}';END IF;
    RETURN NEXT erp_reports_private.fact(x->>'id',NULL,dim||y);
   ELSE
    FOR doc IN SELECT * FROM erp_reports_private.linked_documents(c,snap->'links',(x->>'id')::uuid) LOOP
     RETURN NEXT erp_reports_private.fact(doc.id::text,(doc.created_at AT TIME ZONE 'Asia/Riyadh')::date,dim||jsonb_build_object('kind',doc.kind,'net',(SELECT coalesce(sum(j.credit-j.debit),0) FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=c AND j.document_id=doc.id AND a.kind='revenue'),'cost',(SELECT coalesce(sum(j.debit-j.credit),0) FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=c AND j.document_id=doc.id AND a.kind='expense'),'profit',(SELECT coalesce(sum(j.credit-j.debit),0) FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=c AND j.document_id=doc.id AND a.kind IN('expense','revenue'))));
    END LOOP;
   END IF;
  END LOOP;RETURN;
 ELSIF s='bookings' THEN
  RETURN QUERY SELECT erp_reports_private.fact(l.id::text,(l.starts_at AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('number',b.number,'name',l.service_name,'customer',p.name,'customerId',p.id,'employee',coalesce(st.name,''),'employeeId',l.staff_id,'branch',br.name,'branchId',b.branch_id,'starts',l.starts_at,'ends',l.ends_at,'status',b.status,'source','booking','href','/dashboard/system/bookings')) FROM public.erp_bookings b JOIN public.erp_booking_lines l ON l.cafe_id=b.cafe_id AND l.booking_id=b.id JOIN public.bf_parties p ON p.cafe_id=b.cafe_id AND p.id=b.customer_id LEFT JOIN public.bf_staff st ON st.cafe_id=l.cafe_id AND st.user_id=l.staff_id LEFT JOIN public.branches br ON br.cafe_id=b.cafe_id AND br.id=b.branch_id WHERE b.cafe_id=c;
  IF erp_access_private.allowed(c,'work_orders','read') THEN
   snap:=public.erp_work_orders_read(c);FOR x IN SELECT value FROM jsonb_array_elements(snap->'records') LOOP
    IF nullif(x->>'start','') IS NOT NULL THEN RETURN NEXT erp_reports_private.fact('work-order:'||(x->>'id'),((x->>'start')::timestamptz AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('number',x->>'code','name',x->>'title','customer',x->>'customerName','employee',x->>'assigneeName','status',x->>'status','source','work_order','starts',x->>'start','ends',x->>'end'));END IF;
   END LOOP;
  END IF;RETURN;
 ELSIF s='installments' THEN
  FOR x IN SELECT erp_installment_private.agreement(c,d.id) FROM public.bf_documents d JOIN public.bf_invoice_management m ON m.cafe_id=d.cafe_id AND m.document_id=d.id WHERE d.cafe_id=c AND d.kind='sale' AND jsonb_typeof(m.metadata->'schedule')='object' LOOP
   FOR y IN SELECT to_jsonb(r) FROM erp_installment_private.rows((x->>'total')::numeric,(x->>'outstanding')::numeric,(x->>'refundedTotal')::numeric,x->'schedule')r LOOP
    RETURN NEXT erp_reports_private.fact((x->>'id')||':'||(y->>'number'),(y->>'date')::date,jsonb_build_object('number',(x->>'invoiceNumber')||' / '||(y->>'number'),'customer',x->>'customerName','customerId',x->>'customerId','due',y->>'date','amount',y->'amount','paid',y->'paid','outstanding',y->'remaining','status',y->>'status','href','/dashboard/system/installments'));
   END LOOP;
  END LOOP;RETURN;
 ELSIF s IN('rental-units','rental-installments','rental-finance') THEN
  snap:=public.erp_rentals_read(c);
  IF s='rental-units' THEN
   FOR x IN SELECT value FROM jsonb_array_elements(snap->'units') LOOP
    SELECT value INTO y FROM jsonb_array_elements(snap->'types') WHERE value->>'id'=x->>'typeId';
    SELECT value INTO dim FROM jsonb_array_elements(snap->'rules') WHERE value->>'id'=y->>'ruleId';
    RETURN NEXT erp_reports_private.fact(x->>'id',NULL,jsonb_build_object('name',x->>'name','type',y->>'name','unit',dim->>'method','amount',CASE dim->>'method' WHEN 'day' THEN dim#>'{rates,day}' WHEN 'hour' THEN dim#>'{rates,hour}' WHEN 'minute' THEN dim#>'{rates,minute}' ELSE NULL END,'status',CASE WHEN(x->>'active')::boolean THEN 'active' ELSE 'inactive' END,'available',CASE WHEN(x->>'active')::boolean AND NOT EXISTS(SELECT 1 FROM public.erp_rental_reservation_units u WHERE u.cafe_id=c AND u.unit_id=(x->>'id')::uuid AND u.active AND u.starts_at<(t+1)::timestamp AT TIME ZONE 'Asia/Riyadh' AND u.ends_at>f::timestamp AT TIME ZONE 'Asia/Riyadh') THEN 'true' ELSE 'false' END));
   END LOOP;RETURN;
  ELSIF s='rental-installments' THEN
   FOR x IN SELECT value FROM jsonb_array_elements(snap->'contracts') LOOP FOR y IN SELECT value FROM jsonb_array_elements(x->'installments') LOOP
    RETURN NEXT erp_reports_private.fact(y->>'id',(y->>'due')::date,jsonb_build_object('due',y->>'due','number',x->>'code','customer',x->>'customerName','customerId',x->>'customerId','name',(SELECT value->>'name' FROM jsonb_array_elements(snap->'units') WHERE value->>'id'=x->>'unitId'),'amount',y->'amount','paid',CASE WHEN y->>'invoiceId' IS NULL THEN 0 ELSE(y->>'invoiceTotal')::numeric-(y->>'outstanding')::numeric END,'outstanding',coalesce(y->'outstanding',y->'amount'),'status',CASE WHEN y->>'invoiceId' IS NULL THEN 'unissued' WHEN(y->>'outstanding')::numeric=0 THEN 'paid' ELSE 'unpaid' END));
   END LOOP;END LOOP;RETURN;
  ELSE
   -- Financial facts use issued document links; unissued booking totals are excluded.
   RETURN QUERY WITH links AS(SELECT r.id source_id,u.unit_id,i.document_id,1.0/count(*) OVER(PARTITION BY r.id) share FROM public.erp_rental_reservations r JOIN public.erp_rental_reservation_units u ON u.cafe_id=r.cafe_id AND u.reservation_id=r.id JOIN public.bf_company_invoices i ON i.cafe_id=r.cafe_id AND i.draft_id=r.draft_id WHERE r.cafe_id=c UNION ALL SELECT x.id,r.unit_id,i.document_id,1.0 FROM public.erp_rental_installments x JOIN public.erp_rental_contracts r ON r.cafe_id=x.cafe_id AND r.id=x.contract_id JOIN public.bf_company_invoices i ON i.cafe_id=x.cafe_id AND i.draft_id=x.draft_id WHERE x.cafe_id=c),moves AS(SELECT l.*,d.id posted_id,d.created_at FROM links l JOIN public.bf_documents d ON d.cafe_id=c AND(d.id=l.document_id OR d.reference_id=l.document_id AND d.kind='refund'))
   SELECT erp_reports_private.fact(m.posted_id::text||':'||m.unit_id::text,(m.created_at AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('name',u.payload->>'name','type',ty.payload->>'name','net',coalesce(sum(j.credit-j.debit) FILTER(WHERE a.kind='revenue'),0)*m.share,'cost',coalesce(sum(j.debit-j.credit) FILTER(WHERE a.kind='expense'),0)*m.share,'profit',coalesce(sum(j.credit-j.debit) FILTER(WHERE a.kind IN('revenue','expense')),0)*m.share)) FROM moves m JOIN public.erp_rental_units u ON u.cafe_id=c AND u.id=m.unit_id LEFT JOIN public.erp_rental_types ty ON ty.cafe_id=c AND ty.id=(u.payload->>'typeId')::uuid JOIN public.bf_journal j ON j.cafe_id=c AND j.document_id=m.posted_id JOIN public.bf_accounts a ON a.cafe_id=c AND a.id=j.account_id GROUP BY m.posted_id,m.unit_id,m.created_at,u.payload,ty.payload,m.share;RETURN;
  END IF;
 ELSIF s='cost-centers' THEN RETURN QUERY SELECT * FROM erp_reports_private.cost_facts(c,f,t);RETURN;
 ELSIF s IN('messages','ai-usage','activity','cheques') THEN RETURN QUERY SELECT * FROM erp_reports_private.settings_facts(c,s,f,t);RETURN;
 END IF;RAISE EXCEPTION 'مصدر التقرير التشغيلي غير معروف';
END $$;
CREATE FUNCTION erp_reports_private.inventory_dimensions(c uuid,i uuid,w uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$SELECT jsonb_build_object('product',p.name,'productId',p.id,'warehouse',wh.name,'warehouseId',wh.id,'category',coalesce(cat.name,''),'categoryId',cat.id,'brand',coalesce(br.name,''),'unit',p.unit) FROM public.bf_items p JOIN public.bf_warehouses wh ON wh.cafe_id=p.cafe_id AND wh.id=w LEFT JOIN public.erp_inventory_items meta ON meta.cafe_id=p.cafe_id AND meta.item_id=p.id LEFT JOIN public.erp_inventory_catalogs cat ON cat.cafe_id=p.cafe_id AND cat.id=meta.category_id LEFT JOIN public.erp_inventory_catalogs br ON br.cafe_id=p.cafe_id AND br.id=meta.brand_id WHERE p.cafe_id=c AND p.id=i$$;
CREATE FUNCTION erp_reports_private.inventory_ledger(c uuid) RETURNS TABLE(id uuid,cafe_id uuid,document_id uuid,item_id uuid,warehouse_id uuid,quantity numeric,unit_cost numeric,valuation_adjustment numeric,cost_status text,created_at timestamptz) LANGUAGE sql STABLE SET search_path='' AS $$
 SELECT m.id,m.cafe_id,m.document_id,m.item_id,m.warehouse_id,m.quantity,m.unit_cost,m.valuation_adjustment,m.cost_status,m.created_at FROM public.bf_movements m WHERE m.cafe_id=c
 UNION ALL
 SELECT md5(v.id::text||':'||(w->>'warehouseId'))::uuid,v.cafe_id,v.document_id,v.item_id,(w->>'warehouseId')::uuid,0::numeric,0::numeric,-(w->>'amount')::numeric,'known',v.created_at FROM public.erp_purchase_value_changes v CROSS JOIN LATERAL jsonb_array_elements(coalesce(v.distribution->'warehouses','[]')) w WHERE v.cafe_id=c
$$;
CREATE FUNCTION erp_reports_private.inventory_facts(c uuid,s text,f date,t date) RETURNS SETOF jsonb LANGUAGE plpgsql SET search_path='' AS $$DECLARE x record;y jsonb;opening numeric;closing numeric;incoming numeric;outgoing numeric;v numeric;known boolean;history boolean;ages jsonb;BEGIN
 IF s='stock-movements' THEN
  RETURN QUERY SELECT erp_reports_private.fact(m.id::text,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date,erp_reports_private.inventory_dimensions(c,m.item_id,m.warehouse_id)||jsonb_build_object('number',d.number,'kind',d.kind,'received',greatest(m.quantity,0),'issued',greatest(-m.quantity,0),'quantity',m.quantity,'value',CASE WHEN m.cost_status IN('known','estimated') THEN round(m.quantity*m.unit_cost,2)-m.valuation_adjustment END,'status',m.cost_status)) FROM erp_reports_private.inventory_ledger(c) m JOIN public.bf_documents d ON d.cafe_id=m.cafe_id AND d.id=m.document_id WHERE m.cafe_id=c AND erp_inventory_private.warehouse_allowed(c,m.warehouse_id);RETURN;
 ELSIF s IN('stock','stock-aging','stock-turnover') THEN
  FOR x IN SELECT * FROM public.bf_stock WHERE cafe_id=c AND erp_inventory_private.warehouse_allowed(c,warehouse_id) LOOP
   SELECT x.quantity-coalesce(sum(m.quantity) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date>=f),0),x.quantity-coalesce(sum(m.quantity) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date>t),0),coalesce(sum(greatest(m.quantity,0)) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t),0),coalesce(sum(greatest(-m.quantity,0)) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t),0),abs(x.quantity-coalesce(sum(m.quantity),0))<0.0005,abs(x.value-coalesce(sum(round(m.quantity*m.unit_cost,2)-m.valuation_adjustment),0))<0.02 AND coalesce(bool_and(m.cost_status IN('known','estimated')),false),x.value-coalesce(sum(round(m.quantity*m.unit_cost,2)-m.valuation_adjustment) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date>t),0) INTO opening,closing,incoming,outgoing,history,known,v FROM erp_reports_private.inventory_ledger(c) m JOIN public.bf_documents d ON d.cafe_id=m.cafe_id AND d.id=m.document_id WHERE m.cafe_id=c AND m.item_id=x.item_id AND m.warehouse_id=x.warehouse_id;
   IF t>=current_date THEN v:=x.value;known:=x.cost_known;END IF;
   y:=erp_reports_private.inventory_dimensions(c,x.item_id,x.warehouse_id)||jsonb_build_object('opening',opening,'received',incoming,'issued',outgoing,'closing',closing,'quantity',closing,'average',CASE WHEN s='stock-turnover' THEN(opening+closing)/2 WHEN known AND closing<>0 THEN v/closing END,'value',CASE WHEN known THEN v END,'turnover',CASE WHEN opening+closing>0 THEN outgoing/((opening+closing)/2) END,'status',CASE WHEN NOT history THEN 'incomplete_history' WHEN NOT known THEN 'unknown_cost' ELSE 'known' END);
   IF s='stock-aging' THEN
    WITH receipts AS(SELECT m.id,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date dated,m.quantity,coalesce(sum(m.quantity) OVER(ORDER BY d.created_at DESC,m.created_at DESC,m.id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) later FROM erp_reports_private.inventory_ledger(c) m JOIN public.bf_documents d ON d.cafe_id=m.cafe_id AND d.id=m.document_id WHERE m.cafe_id=c AND m.item_id=x.item_id AND m.warehouse_id=x.warehouse_id AND m.quantity>0 AND(d.created_at AT TIME ZONE 'Asia/Riyadh')::date<=t),remaining AS(SELECT dated,least(quantity,greatest(0,closing-later)) q FROM receipts)
    SELECT jsonb_build_object('age30',CASE WHEN history THEN coalesce(sum(q) FILTER(WHERE t-dated<=30),0) END,'age60',CASE WHEN history THEN coalesce(sum(q) FILTER(WHERE t-dated BETWEEN 31 AND 60),0) END,'age90',CASE WHEN history THEN coalesce(sum(q) FILTER(WHERE t-dated BETWEEN 61 AND 90),0) END,'ageOlder',CASE WHEN history THEN coalesce(sum(q) FILTER(WHERE t-dated>90),0) END) INTO ages FROM remaining;y:=y||ages;
   END IF;RETURN NEXT erp_reports_private.fact(x.item_id::text||':'||x.warehouse_id::text,NULL,y);
  END LOOP;RETURN;
 ELSIF s='stock-requests' THEN
  RETURN QUERY SELECT erp_reports_private.fact(l.id::text,d.effective_on,erp_reports_private.inventory_dimensions(c,l.item_id,d.warehouse_id)||jsonb_build_object('number',d.code,'kind',CASE WHEN original.kind IN('sale','purchase') THEN original.kind ELSE fd.kind END,'customer',CASE WHEN p.kind='customer' THEN p.name ELSE '' END,'supplier',CASE WHEN p.kind='supplier' THEN p.name ELSE '' END,'quantity',l.quantity*l.factor,'status',d.status,'href','/dashboard/system/inventory/'||CASE d.kind WHEN 'request' THEN 'requests' ELSE 'requisitions' END||'/'||d.id)) FROM public.erp_inventory_documents d JOIN public.erp_inventory_lines l ON l.cafe_id=d.cafe_id AND l.document_id=d.id LEFT JOIN public.bf_documents fd ON fd.cafe_id=d.cafe_id AND fd.id=d.finance_document_id LEFT JOIN public.bf_documents original ON original.cafe_id=fd.cafe_id AND original.id=fd.reference_id LEFT JOIN public.bf_parties p ON p.cafe_id=d.cafe_id AND p.id=d.party_id WHERE d.cafe_id=c AND erp_inventory_private.warehouse_allowed(c,d.warehouse_id);RETURN;
 ELSIF s='manufacturing' THEN
  RETURN QUERY SELECT erp_reports_private.fact(o.id::text,(coalesce(d.created_at,o.created_at) AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('number',o.code,'product',o.name,'kind','order','quantity',o.output_quantity,'cost',o.material_cost+o.additional_cost,'status',o.status,'href','/dashboard/system/manufacturing/orders/'||o.id)) FROM public.erp_mfg_orders o LEFT JOIN public.bf_documents d ON d.cafe_id=o.cafe_id AND d.id=o.output_document_id WHERE o.cafe_id=c AND(d.warehouse_id IS NULL OR erp_inventory_private.warehouse_allowed(c,d.warehouse_id)) AND NOT EXISTS(SELECT 1 FROM public.erp_mfg_material_issues mi WHERE mi.cafe_id=c AND mi.order_id=o.id AND NOT erp_inventory_private.warehouse_allowed(c,mi.warehouse_id));RETURN;
 ELSIF s='assets' THEN
  RETURN QUERY SELECT erp_reports_private.fact(a.id::text,NULL,jsonb_build_object('number',a.code,'name',a.name,'category',cat.name,'amount',a.gross_value,'cost',a.accumulated_depreciation,'balance',a.gross_value-a.accumulated_depreciation,'status',a.status,'starts',a.acquired_on,'employee',(SELECT string_agg(DISTINCT coalesce(e.first_name||' '||e.last_name,st.name),'، ') FROM public.erp_asset_units u LEFT JOIN public.erp_hr_employees e ON e.cafe_id=u.cafe_id AND e.id=nullif(to_jsonb(u)->>'employee_profile_id','')::uuid LEFT JOIN public.bf_staff st ON st.cafe_id=u.cafe_id AND st.user_id=u.employee_id WHERE u.cafe_id=c AND u.asset_id=a.id AND u.status='in_service'),'href','/dashboard/system/assets/'||a.id)) FROM public.erp_assets a LEFT JOIN public.bf_accounts cat ON cat.cafe_id=a.cafe_id AND cat.id=(a.payload->>'assetAccountId')::uuid WHERE a.cafe_id=c;RETURN;
 END IF;RAISE EXCEPTION 'مصدر تقرير المخزون غير معروف';
END $$;
CREATE FUNCTION erp_reports_private.cost_facts(c uuid,f date,t date) RETURNS SETOF jsonb LANGUAGE plpgsql SET search_path='' AS $$BEGIN
 PERFORM erp_access_private.assert_allowed(c,'accounting','read');PERFORM erp_access_private.assert_allowed(c,'finance','read');PERFORM erp_access_private.assert_allowed(c,'purchases','read');
 RETURN QUERY WITH raw AS(
  SELECT a.center_id,vd.id document_id,vd.created_at dated,'voucher'::text kind,CASE ac.kind WHEN 'revenue' THEN a.base_amount ELSE 0 END income,CASE ac.kind WHEN 'expense' THEN a.base_amount ELSE 0 END expense,0::numeric capitalized FROM public.erp_finance_cost_allocations a JOIN public.erp_finance_vouchers v ON v.cafe_id=a.cafe_id AND v.id=a.voucher_id JOIN public.bf_documents vd ON vd.cafe_id=v.cafe_id AND vd.id=v.document_id JOIN public.bf_accounts ac ON ac.cafe_id=v.cafe_id AND ac.id=(v.payload->'lines'->a.line_index->>'accountId')::uuid WHERE a.cafe_id=c
  UNION ALL SELECT a.center_id,vd.id,vd.created_at,'voucher_reversal',CASE ac.kind WHEN 'revenue' THEN -a.base_amount ELSE 0 END,CASE ac.kind WHEN 'expense' THEN -a.base_amount ELSE 0 END,0 FROM public.erp_finance_cost_allocations a JOIN public.erp_finance_vouchers v ON v.cafe_id=a.cafe_id AND v.id=a.voucher_id JOIN public.bf_documents vd ON vd.cafe_id=v.cafe_id AND vd.id=v.reversal_id JOIN public.bf_accounts ac ON ac.cafe_id=v.cafe_id AND ac.id=(v.payload->'lines'->a.line_index->>'accountId')::uuid WHERE a.cafe_id=c
  UNION ALL SELECT a.center_id,d.id,d.created_at,'custody',0,a.base_amount,0 FROM public.erp_finance_custody_costs a JOIN public.erp_finance_custody_movements m ON m.cafe_id=a.cafe_id AND m.id=a.movement_id JOIN public.bf_documents d ON d.cafe_id=m.cafe_id AND d.id=m.document_id JOIN public.bf_accounts ac ON ac.cafe_id=a.cafe_id AND ac.id=(m.payload->'lines'->a.line_index->>'accountId')::uuid WHERE a.cafe_id=c AND ac.kind='expense'
  UNION ALL SELECT a.center_id,d.id,d.created_at,'custody_reversal',0,-a.base_amount,0 FROM public.erp_finance_custody_costs a JOIN public.erp_finance_custody_movements m ON m.cafe_id=a.cafe_id AND m.id=a.movement_id JOIN public.erp_finance_custody_movements r ON r.cafe_id=m.cafe_id AND r.reversal_of=m.id JOIN public.bf_documents d ON d.cafe_id=r.cafe_id AND d.id=r.document_id JOIN public.bf_accounts ac ON ac.cafe_id=a.cafe_id AND ac.id=(m.payload->'lines'->a.line_index->>'accountId')::uuid WHERE a.cafe_id=c AND ac.kind='expense'
  UNION ALL SELECT a.cost_center_id,doc.id,doc.created_at,'journal',CASE WHEN ac.kind='revenue' THEN((l->>'credit')::numeric-(l->>'debit')::numeric)*a.percentage/100 ELSE 0 END,CASE WHEN ac.kind='expense' THEN((l->>'debit')::numeric-(l->>'credit')::numeric)*a.percentage/100 ELSE 0 END,CASE WHEN ac.kind IN('inventory','fixed_asset') THEN((l->>'debit')::numeric-(l->>'credit')::numeric)*a.percentage/100 ELSE 0 END FROM public.erp_accounting_allocations a JOIN public.bf_gl_drafts dr ON dr.cafe_id=a.cafe_id AND dr.id=a.draft_id JOIN public.bf_documents doc ON doc.cafe_id=dr.cafe_id AND doc.id=dr.document_id CROSS JOIN LATERAL jsonb_array_elements(dr.lines) WITH ORDINALITY lines(l,n) JOIN public.bf_accounts ac ON ac.cafe_id=a.cafe_id AND ac.id=(l->>'accountId')::uuid WHERE a.cafe_id=c AND n=a.line_index+1
  UNION ALL SELECT a.cost_center_id,doc.id,doc.created_at,'journal_reversal',CASE WHEN ac.kind='revenue' THEN((l->>'debit')::numeric-(l->>'credit')::numeric)*a.percentage/100 ELSE 0 END,CASE WHEN ac.kind='expense' THEN((l->>'credit')::numeric-(l->>'debit')::numeric)*a.percentage/100 ELSE 0 END,CASE WHEN ac.kind IN('inventory','fixed_asset') THEN((l->>'credit')::numeric-(l->>'debit')::numeric)*a.percentage/100 ELSE 0 END FROM public.erp_accounting_allocations a JOIN public.bf_gl_drafts dr ON dr.cafe_id=a.cafe_id AND dr.id=a.draft_id JOIN public.bf_documents doc ON doc.cafe_id=dr.cafe_id AND doc.id=dr.reversal_document_id CROSS JOIN LATERAL jsonb_array_elements(dr.lines) WITH ORDINALITY lines(l,n) JOIN public.bf_accounts ac ON ac.cafe_id=a.cafe_id AND ac.id=(l->>'accountId')::uuid WHERE a.cafe_id=c AND n=a.line_index+1
  UNION ALL SELECT a.cost_center_id,d.id,d.created_at,'purchase',0,CASE WHEN l.item_id IS NULL THEN a.amount ELSE 0 END,CASE WHEN l.item_id IS NOT NULL THEN a.amount ELSE 0 END FROM public.erp_purchase_line_centers a JOIN public.bf_document_lines l ON l.cafe_id=a.cafe_id AND l.id=a.line_id JOIN public.bf_documents d ON d.cafe_id=a.cafe_id AND d.id=a.document_id WHERE a.cafe_id=c
  UNION ALL SELECT a.cost_center_id,d.id,d.created_at,'purchase_return',0,CASE WHEN l.item_id IS NULL THEN -l.net ELSE 0 END,CASE WHEN l.item_id IS NOT NULL THEN -l.net ELSE 0 END FROM public.erp_purchase_line_centers a JOIN public.bf_document_lines l ON l.cafe_id=a.cafe_id AND l.reference_line_id=a.line_id JOIN public.bf_documents d ON d.cafe_id=l.cafe_id AND d.id=l.document_id AND d.kind='refund' WHERE a.cafe_id=c
  UNION ALL SELECT a.cost_center_id,d.id,d.created_at,'purchase_debit',0,CASE WHEN l.item_id IS NULL THEN -db.net ELSE 0 END,CASE WHEN l.item_id IS NOT NULL THEN -db.net ELSE 0 END FROM public.erp_purchase_line_centers a JOIN public.erp_purchase_debits db ON db.cafe_id=a.cafe_id AND db.line_id=a.line_id JOIN public.bf_document_lines l ON l.cafe_id=a.cafe_id AND l.id=a.line_id JOIN public.bf_documents d ON d.cafe_id=db.cafe_id AND d.id=db.document_id WHERE a.cafe_id=c
 ), adjusted AS(
  SELECT * FROM raw
  UNION ALL SELECT r.center_id,d.id,d.created_at,'allocated_expense',0,-p.amount*r.expense/nullif((SELECT sum(j.debit-j.credit) FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=c AND j.document_id=p.expense_document_id AND a.kind='expense'),0),0 FROM public.erp_purchase_allocations p JOIN raw r ON r.document_id=p.expense_document_id AND r.expense>0 JOIN public.bf_documents d ON d.cafe_id=p.cafe_id AND d.id=p.posting_document_id WHERE p.cafe_id=c
  UNION ALL SELECT lc.cost_center_id,d.id,d.created_at,'allocated_purchase',0,(line->>'cogs')::numeric,(line->>'inventory')::numeric FROM public.erp_purchase_allocations p CROSS JOIN LATERAL jsonb_array_elements(p.payload->'lines')line JOIN public.erp_purchase_line_centers lc ON lc.cafe_id=p.cafe_id AND lc.line_id=(line->>'lineId')::uuid JOIN public.bf_documents d ON d.cafe_id=p.cafe_id AND d.id=p.posting_document_id WHERE p.cafe_id=c
 ) SELECT erp_reports_private.fact(a.document_id::text||':'||a.center_id::text||':'||a.kind,(a.dated AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('center',cc.name,'centerId',cc.id,'kind',a.kind,'amount',sum(a.income),'cost',sum(a.expense),'value',sum(a.capitalized),'estimatedCost',0,'cashPaid',NULL)) FROM adjusted a JOIN public.erp_cost_centers cc ON cc.cafe_id=c AND cc.id=a.center_id WHERE(a.dated AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t GROUP BY a.document_id,a.center_id,a.kind,a.dated,cc.name,cc.id;
END $$;
CREATE FUNCTION erp_reports_private.settings_facts(c uuid,s text,f date,t date) RETURNS SETOF jsonb LANGUAGE plpgsql SET search_path='' AS $$DECLARE x jsonb;table_name text;label text;actor uuid;BEGIN
 IF s='cheques' THEN FOR x IN SELECT value FROM jsonb_array_elements(public.erp_cheques_report(c,f,t)->'rows') LOOP RETURN NEXT erp_reports_private.fact(x->>'id',(x->>'date')::date,x||'{"currency":"SAR"}'::jsonb);END LOOP;RETURN;
 ELSIF s='messages' THEN
  RETURN QUERY SELECT erp_reports_private.fact(d.id::text,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('name',coalesce(nullif(d.subject,''),tm.name),'type',d.channel,'status',d.status,'count',1)) FROM public.erp_template_deliveries d JOIN public.erp_document_templates tm ON tm.cafe_id=d.cafe_id AND tm.id=d.template_id WHERE d.cafe_id=c AND d.channel='sms';RETURN;
 ELSIF s='ai-usage' THEN
  IF to_regclass('public.erp_ai_usage') IS NOT NULL THEN RETURN QUERY EXECUTE 'SELECT erp_reports_private.fact(u.id::text,(u.created_at AT TIME ZONE ''Asia/Riyadh'')::date,jsonb_build_object(''employee'',coalesce(st.name,''''),''employeeId'',u.actor,''type'',u.operation,''quantity'',u.units,''status'',u.status)) FROM public.erp_ai_usage u LEFT JOIN public.bf_staff st ON st.cafe_id=u.cafe_id AND st.user_id=u.actor WHERE u.cafe_id=$1' USING c;END IF;RETURN;
 ELSIF s='activity' THEN
  FOR table_name,label IN SELECT * FROM(VALUES('bf_invoice_activity','المبيعات'),('erp_finance_events','المالية'),('erp_accounting_events','الحسابات العامة'),('erp_purchase_events','المشتريات'),('erp_inventory_events','المخزون'),('erp_mfg_events','التصنيع'),('erp_customer_events','العملاء'),('erp_membership_events','العضويات'),('erp_credit_events','أرصدة الخدمات'),('erp_hr_events','الموظفون'),('erp_att_events','الحضور'),('erp_payroll_events','المرتبات'),('erp_rental_events','الإيجارات'),('erp_work_order_events','أوامر الشغل'),('erp_workflow_events','دورات العمل'),('erp_time_events','تتبع الوقت'),('erp_cheque_audit','الشيكات'),('erp_request_events','الطلبات'),('erp_report_events','التقارير'),('erp_settings_events','الإعدادات'),('erp_customer_portal_events','بوابة العميل'))q(tab,title) LOOP
   IF to_regclass('public.'||table_name) IS NULL THEN CONTINUE;END IF;
   FOR x IN EXECUTE format('SELECT to_jsonb(e) FROM public.%I e WHERE cafe_id=$1 AND(coalesce(to_jsonb(e)->>''created_at'',to_jsonb(e)->>''at'')::timestamptz AT TIME ZONE ''Asia/Riyadh'')::date BETWEEN $2 AND $3',table_name) USING c,f,t LOOP
    actor:=coalesce(x->>'actor',x->>'actor_id',x->>'created_by')::uuid;
    RETURN NEXT erp_reports_private.fact(table_name||':'||(x->>'id'),(coalesce(x->>'created_at',x->>'at')::timestamptz AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('employee',coalesce((SELECT name FROM public.bf_staff WHERE cafe_id=c AND user_id=actor),(SELECT 'المالك' FROM public.cafes WHERE id=c AND owner_user_id=actor),''),'employeeId',actor,'type',label,'name',x->>'action','note',coalesce(x->>'note','')));
   END LOOP;
  END LOOP;RETURN;
 END IF;RAISE EXCEPTION 'مصدر تقرير الإعدادات غير معروف';
END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA erp_reports_private FROM PUBLIC,anon,authenticated,service_role;
COMMIT;
